{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": ["C"],
      "content": "Hey, I'm working on getting a triangle for my order. Since you have the specialty triangle, maybe we can trade? I can produce squares if you're open to it."
    }
  },
  "rationale": "C has the specialty triangle, which matches my order. I can offer to trade squares for triangles to help fulfill my order efficiently and build a cooperative relationship."
}

{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "A"
      ],
      "content": "Hey, I'm working on getting a circle for my order. Since you make circles, maybe we can trade? I can produce triangles if you're open to it."
    }
  },
  "rationale": "I need a circle to fulfill my order, and A has the specialty shape. Starting a direct conversation to explore a trade makes sense and aligns with my outgoing, people-focused nature."
}

{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "B"
      ],
      "content": "Hey, I'm working on getting a square for my order. Since you're the specialist in squares, I was wondering if you'd be open to trading a circle for one of your squares? Maybe around $20?"
    }
  },
  "rationale": "I need a square to fulfill my order, and B has the specialty shape. A direct, low-pressure message to propose a fair trade makes sense given my limited production capacity and the need to act quickly."
}

